using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO.Compression;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Xml.Linq;

namespace MissionPlanner.Utilities
{
    // Immutable release snapshots, generated by the matching ArduPilot parser.
    // Index once per requested version instead of scanning the XML for every cell.
    public static class VersionedParameterMetadata
    {
        private const string Prefix = "MissionPlanner.ParameterMetadata.";
        private static readonly HashSet<string> Resources = new HashSet<string>(
            typeof(VersionedParameterMetadata).Assembly.GetManifestResourceNames(), StringComparer.Ordinal);
        private static readonly ConcurrentDictionary<string, Lazy<Dictionary<string, Dictionary<string, string>>>> Indexes =
            new ConcurrentDictionary<string, Lazy<Dictionary<string, Dictionary<string, string>>>>();

        private static string ResourceKey(string key) => key != null && key.StartsWith("Heli", StringComparison.Ordinal)
            ? "Copter" + key.Substring(4) : key;

        public static bool ContainsVersion(string key) => Resources.Contains(Prefix + ResourceKey(key) + ".apm.pdef.xml.gz");

        public static bool TryGet(string key, string name, string field, out string value)
        {
            value = string.Empty;
            if (!ContainsVersion(key)) return false;
            var index = Indexes.GetOrAdd(key, k => new Lazy<Dictionary<string, Dictionary<string, string>>>(
                () => Load(k), LazyThreadSafetyMode.ExecutionAndPublication)).Value;
            if (index.TryGetValue(name, out var parameter) && parameter.TryGetValue(field, out var found))
                value = found;
            // An absent field/name must stay absent, never inherit another release.
            return true;
        }

        private static Dictionary<string, Dictionary<string, string>> Load(string key)
        {
            using (var resource = typeof(VersionedParameterMetadata).Assembly.GetManifestResourceStream(Prefix + ResourceKey(key) + ".apm.pdef.xml.gz"))
            using (var gzip = new GZipStream(resource, CompressionMode.Decompress))
            {
                var index = new Dictionary<string, Dictionary<string, string>>(StringComparer.Ordinal);
                var helicopter = key.StartsWith("Heli", StringComparison.Ordinal);
                var nodes = XDocument.Load(gzip).Descendants("param");
                // Copter's documentation includes both controllers. Prefer the
                // matching frame's definitions without dropping unique parameters.
                nodes = nodes.OrderByDescending(node =>
                {
                    var source = (string)node.Attribute("source") ?? "";
                    return helicopter
                        ? source.EndsWith("AC_AttitudeControl_Heli.cpp", StringComparison.Ordinal) || source.EndsWith("AC_AutoTune_Heli.cpp", StringComparison.Ordinal)
                        : source.EndsWith("AC_AttitudeControl_Multi.cpp", StringComparison.Ordinal) || source.EndsWith("AC_AutoTune_Multi.cpp", StringComparison.Ordinal);
                });
                foreach (var node in nodes)
                {
                    var name = ((string)node.Attribute("name") ?? "").Split(':').Last();
                    // Other hardware-dependent duplicates retain upstream order;
                    // every definition remains available in the audit report.
                    if (name.Length == 0 || index.ContainsKey(name)) continue;
                    var fields = new Dictionary<string, string>(StringComparer.Ordinal)
                    {
                        [ParameterMetaDataConstants.DisplayName] = (string)node.Attribute("humanName") ?? "",
                        [ParameterMetaDataConstants.Description] = (string)node.Attribute("documentation") ?? "",
                        [ParameterMetaDataConstants.User] = (string)node.Attribute("user") ?? "",
                        [ParameterMetaDataConstants.Values] = string.Concat(node.Elements("values").Elements("value")
                            .Select(v => (string)v.Attribute("code") + ":" + v.Value + ","))
                    };
                    foreach (var field in node.Elements("field"))
                    {
                        var fieldName = (string)field.Attribute("name");
                        if (fieldName != null && !fields.ContainsKey(fieldName)) fields[fieldName] = field.Value;
                    }
                    index.Add(name, fields);
                }
                return index;
            }
        }
    }
}
